import React from 'react';
import { chakra, useStyleConfig } from '@chakra-ui/react';
import { ZimmIcon } from 'app/components/ui-kits/atoms/zimmIcon';

const ZIMM_WISHLIST_BADGE_RECIPE = 'ZimmWishlistBadge';

type ZimmWishlistBadgeProps = {
  /** Whether the current product/variant is already in the wishlist — swaps the icon between
   *  the outline ("Default") and solid ("Selected") states (Figma node 40000214:6159). */
  isSelected: boolean;
  isDisabled?: boolean;
  isLoading?: boolean;
  onClick?: () => void;
  /** Required — icon-only control, no visible text. */
  'aria-label': string;
};

/**
 * Atom — the PDP wishlist toggle badge, rendered beside the product name (Figma nodes
 * 40003021:101731/101734). A plain native `<button>` via the chakra factory — deliberately not
 * Chakra's `Button`/`IconButton`, so this control has no shared styling surface with
 * zimmButton.css.ts's `Button` recipe (used by Add to Bag and every other button in the app)
 * and can't be affected by, or affect, it. `IconButton` is avoided specifically because it
 * hard-sets `padding: "0"` as a style prop, which would silently discard this control's 4px
 * padding.
 *
 * Purely presentational — size-gating, auth-gating, and the add-vs-remove decision all live in
 * `ProductView`; this component only renders the current state and forwards clicks.
 */
export const ZimmWishlistBadge = ({
  isSelected,
  isDisabled = false,
  isLoading = false,
  onClick,
  'aria-label': ariaLabel,
}: ZimmWishlistBadgeProps) => {
  const styles = useStyleConfig(ZIMM_WISHLIST_BADGE_RECIPE, {});

  return (
    <chakra.button
      type="button"
      aria-label={ariaLabel}
      onClick={onClick}
      disabled={isDisabled || isLoading}
      __css={styles}
      data-testid="add-to-wishlist-button"
    >
      <ZimmIcon type={isSelected ? 'wishlist-solid' : 'wishlist'} size="md" aria-hidden={true} />
    </chakra.button>
  );
};

